create table if not exists users(id bigint generated always as identity primary key,name text not null,email text unique not null,password_hash text not null,created_at timestamptz default now()); create table if not exists chats(id bigint generated always as identity primary key,user_id bigint references users(id),title text,created_at timestamptz default now()); create table if not exists messages(id bigint generated always as identity primary key,chat_id bigint references chats(id) on delete cascade,role text not null,content text not null,created_at timestamptz default now()); create table if not exists documents(id bigint generated always as identity primary key,user_id bigint references users(id),name text,mime text,size bigint,storage_path text,created_at timestamptz default now()); create table if not exists applications(id bigint generated always as identity primary key,user_id bigint references users(id),country text,visa_type text,status text,created_at timestamptz default now()); create table if not exists payments(id bigint generated always as identity primary key,user_id bigint references users(id),plan text,amount_cents int,currency text,status text,stripe_session_id text,created_at timestamptz default now()); create table if not exists agent_runs(id text primary key,user_id bigint,task text,engine text,status text,result text,created_at timestamptz default now());